using bloodPressureWebApi.DTOs.E1;
using bloodPressureWebApi.DTOs.Experiments;
using bloodPressureWebApi.Services.Interfaces;
using System.Globalization;
using System.Text;

namespace bloodPressureWebApi.Services
{
    /// <summary>
    /// Reads the MATLAB scientific reference generated by pruebaGeneral.
    /// </summary>
    public class E1BReferenceService : IE1BReferenceService
    {
        private const string CsvPath =
            @"C:\MAPA_E1_TEST\E1B_MATLAB_REFERENCE.csv";

        private readonly SemaphoreSlim _loadLock = new(1, 1);

        private Dictionary<string, E1MatlabReferenceDto> _reference =
            new(StringComparer.OrdinalIgnoreCase);

        private bool _loaded;

        private static readonly string[] RequiredColumns =
        {
            "FileName",
            "Age",
            "SysANN",
            "DiaANN",
            "PulseANN",
            "BPLevelOutput",
            "HeartRateOutput",
            "Sdia",
            "Ddia",
            "Snoche",
            "Dnoche",
            "Csis",
            "Cdia",
            "NocturnalOutput",
            "NocturnalProfile",
            "Status",
            "ErrorMessage"
        };

        //====================================================
        // LOAD REFERENCE
        //====================================================

        public async Task<Dictionary<string, E1MatlabReferenceDto>>
            LoadReferenceAsync()
        {
            if (_loaded)
                return _reference;

            await _loadLock.WaitAsync();

            try
            {
                if (_loaded)
                    return _reference;

                if (!File.Exists(CsvPath))
                {
                    throw new FileNotFoundException(
                        $"MATLAB reference not found: {CsvPath}",
                        CsvPath);
                }

                var lines = await File.ReadAllLinesAsync(
                    CsvPath,
                    Encoding.UTF8);

                if (lines.Length < 2)
                {
                    throw new InvalidDataException(
                        "The MATLAB reference CSV contains no data rows.");
                }

                var headers = ParseCsvLine(lines[0])
                    .Select((name, index) => new
                    {
                        Name = name.Trim().TrimStart('\uFEFF'),
                        Index = index
                    })
                    .ToDictionary(
                        x => x.Name,
                        x => x.Index,
                        StringComparer.OrdinalIgnoreCase);

                var missingColumns = RequiredColumns
                    .Where(column => !headers.ContainsKey(column))
                    .ToArray();

                if (missingColumns.Length > 0)
                {
                    throw new InvalidDataException(
                        "The MATLAB reference CSV is missing columns: " +
                        string.Join(", ", missingColumns));
                }

                var loadedReference =
                    new Dictionary<string, E1MatlabReferenceDto>(
                        StringComparer.OrdinalIgnoreCase);

                for (int i = 1; i < lines.Length; i++)
                {
                    if (string.IsNullOrWhiteSpace(lines[i]))
                        continue;

                    try
                    {
                        var values = ParseCsvLine(lines[i]);

                        string fileName = GetValue(
                            values, headers, "FileName");

                        if (string.IsNullOrWhiteSpace(fileName))
                        {
                            throw new InvalidDataException(
                                "FileName is empty.");
                        }

                        var dto = new E1MatlabReferenceDto
                        {
                            FileName = fileName,
                            Age = ParseInt(
                                GetValue(values, headers, "Age"),
                                "Age"),

                            SysANN = ParseDouble(
                                GetValue(values, headers, "SysANN"),
                                "SysANN"),

                            DiaANN = ParseDouble(
                                GetValue(values, headers, "DiaANN"),
                                "DiaANN"),

                            PulseANN = ParseDouble(
                                GetValue(values, headers, "PulseANN"),
                                "PulseANN"),

                            BPLevelOutput = ParseDouble(
                                GetValue(values, headers, "BPLevelOutput"),
                                "BPLevelOutput"),

                            HeartRateOutput = ParseDouble(
                                GetValue(values, headers, "HeartRateOutput"),
                                "HeartRateOutput"),

                            Sdia = ParseDouble(
                                GetValue(values, headers, "Sdia"),
                                "Sdia"),

                            Ddia = ParseDouble(
                                GetValue(values, headers, "Ddia"),
                                "Ddia"),

                            Snoche = ParseDouble(
                                GetValue(values, headers, "Snoche"),
                                "Snoche"),

                            Dnoche = ParseDouble(
                                GetValue(values, headers, "Dnoche"),
                                "Dnoche"),

                            Csis = ParseDouble(
                                GetValue(values, headers, "Csis"),
                                "Csis"),

                            Cdia = ParseDouble(
                                GetValue(values, headers, "Cdia"),
                                "Cdia"),

                            NocturnalOutput = ParseDouble(
                                GetValue(values, headers, "NocturnalOutput"),
                                "NocturnalOutput"),

                            NocturnalProfile = GetValue(
                                values, headers, "NocturnalProfile"),

                            Status = GetValue(
                                values, headers, "Status"),

                            ErrorMessage = GetValue(
                                values, headers, "ErrorMessage")
                        };

                        if (!string.Equals(
                            dto.Status,
                            "OK",
                            StringComparison.OrdinalIgnoreCase))
                        {
                            throw new InvalidDataException(
                                $"Reference row has Status='{dto.Status}'. " +
                                $"ErrorMessage='{dto.ErrorMessage}'.");
                        }

                        if (string.IsNullOrWhiteSpace(
                            dto.NocturnalProfile))
                        {
                            throw new InvalidDataException(
                                "NocturnalProfile is empty.");
                        }

                        if (!loadedReference.TryAdd(
                            dto.FileName,
                            dto))
                        {
                            throw new InvalidDataException(
                                $"Duplicate FileName: {dto.FileName}");
                        }
                    }
                    catch (Exception ex)
                    {
                        throw new InvalidDataException(
                            $"Invalid MATLAB reference at CSV line {i + 1}: " +
                            ex.Message,
                            ex);
                    }
                }

                if (loadedReference.Count == 0)
                {
                    throw new InvalidDataException(
                        "No valid MATLAB reference records were loaded.");
                }

                _reference = loadedReference;
                _loaded = true;

                return _reference;
            }
            finally
            {
                _loadLock.Release();
            }
        }

        //====================================================
        // ENSURE LOADED
        //====================================================

        private void EnsureLoaded()
        {
            if (!_loaded)
            {
                LoadReferenceAsync()
                    .GetAwaiter()
                    .GetResult();
            }
        }

        //====================================================
        // EXISTS
        //====================================================

        public bool Exists(string fileName)
        {
            EnsureLoaded();

            return _reference.ContainsKey(
                Path.GetFileName(fileName));
        }

        //====================================================
        // GET REFERENCE
        //====================================================

        public E1MatlabReferenceDto? GetReference(
            string fileName)
        {
            EnsureLoaded();

            _reference.TryGetValue(
                Path.GetFileName(fileName),
                out var value);

            return value;
        }

        //====================================================
        // GET ALL
        //====================================================

        public IReadOnlyDictionary<string, E1MatlabReferenceDto>
            GetAll()
        {
            EnsureLoaded();

            return _reference;
        }

        //====================================================
        // GET CSV VALUE BY HEADER
        //====================================================

        private static string GetValue(
            IReadOnlyList<string> values,
            IReadOnlyDictionary<string, int> headers,
            string column)
        {
            int index = headers[column];

            if (index >= values.Count)
            {
                throw new InvalidDataException(
                    $"Missing value for column '{column}'.");
            }

            return values[index].Trim();
        }

        //====================================================
        // CSV PARSER: SUPPORTS QUOTED FIELDS AND COMMAS
        //====================================================

        private static List<string> ParseCsvLine(string line)
        {
            var fields = new List<string>();
            var field = new StringBuilder();
            bool inQuotes = false;

            for (int i = 0; i < line.Length; i++)
            {
                char c = line[i];

                if (c == '"')
                {
                    if (inQuotes &&
                        i + 1 < line.Length &&
                        line[i + 1] == '"')
                    {
                        field.Append('"');
                        i++;
                    }
                    else
                    {
                        inQuotes = !inQuotes;
                    }
                }
                else if (c == ',' && !inQuotes)
                {
                    fields.Add(field.ToString());
                    field.Clear();
                }
                else
                {
                    field.Append(c);
                }
            }

            if (inQuotes)
            {
                throw new InvalidDataException(
                    "The CSV row contains an unclosed quoted field.");
            }

            fields.Add(field.ToString());

            return fields;
        }

        //====================================================
        // PARSE DOUBLE
        //====================================================

        private static double ParseDouble(
            string value,
            string column)
        {
            if (string.IsNullOrWhiteSpace(value))
            {
                throw new InvalidDataException(
                    $"Numeric column '{column}' is empty.");
            }

            if (!double.TryParse(
                value.Trim(),
                NumberStyles.Float,
                CultureInfo.InvariantCulture,
                out double result) ||
                !double.IsFinite(result))
            {
                throw new InvalidDataException(
                    $"Invalid numeric value '{value}' in '{column}'.");
            }

            return result;
        }

        //====================================================
        // PARSE INT
        //====================================================

        private static int ParseInt(
            string value,
            string column)
        {
            if (!int.TryParse(
                value.Trim(),
                NumberStyles.Integer,
                CultureInfo.InvariantCulture,
                out int result))
            {
                throw new InvalidDataException(
                    $"Invalid integer value '{value}' in '{column}'.");
            }

            return result;
        }

        //====================================================
        // RELOAD
        //====================================================

        public async Task ReloadAsync()
        {
            await _loadLock.WaitAsync();

            try
            {
                _loaded = false;
                _reference.Clear();
            }
            finally
            {
                _loadLock.Release();
            }

            await LoadReferenceAsync();
        }
    }
}